INSERT INTO runtime_delivery_units(operation_id,attempt,ordinal,artifact_count,status) SELECT o.id,?2,?5,?6,'sending' FROM runtime_operations o WHERE o.id=?1 AND o.attempt=?2 AND o.lease_token=?3 AND o.worker_id=?4 AND o.status='delivering' AND o.lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) AND o.planned_artifact_count IS NOT NULL AND o.cancel_requested=0 AND ?5=COALESCE((SELECT MAX(ordinal)+1 FROM runtime_delivery_units WHERE operation_id=o.id AND attempt=o.attempt),0) AND o.delivered_artifact_count=COALESCE((SELECT SUM(artifact_count) FROM runtime_delivery_units WHERE operation_id=o.id AND attempt=o.attempt AND status='sent'),0) AND ?6<=10 AND ?6<=o.planned_artifact_count-o.delivered_artifact_count AND NOT EXISTS(SELECT 1 FROM runtime_delivery_units WHERE operation_id=o.id AND attempt=o.attempt AND status<>'sent') ON CONFLICT(operation_id,attempt,ordinal) DO NOTHING;